const net = require('node:net');
const frame = (obj) => {                      // forwarder: envelope + framing
  const body = Buffer.from(JSON.stringify(obj));
  const head = Buffer.alloc(4); head.writeUInt32BE(body.length);
  return Buffer.concat([head, body]);
};
net.createConnection(9002, 'peer2').write(frame({ type: 'order.created', id: 7 }));

const handlers = { 'order.created': (m) => peer.onCreated(m) };   // receiver
net.createServer((c) => c.pipe(new LengthFramer()).on('data', (body) => {
  const msg = JSON.parse(body); handlers[msg.type]?.(msg);
})).listen(9002);
